async function idsForScope(){const all=state.records,scope=state.scope,target=state.scopeTarget;if(scope==='reset-all')return all.map(r=>String(r.id));if(scope==='diagnostics'){const ids=new Set();for(const run of await readStoreRows('genreactrix-prompt-diagnostics','runs').catch(()=>[]))if(run?.value?.imageId)ids.add(String(run.value.imageId));return [...ids]}if(scope==='pack')return all.filter(r=>packIdsOf(r).includes(String(target))).map(r=>String(r.id));if(scope==='bundle')return all.filter(r=>bundleIdsOf(r).includes(String(target))).map(r=>String(r.id));if(scope==='batch')return all.filter(r=>batchIdsOf(r).includes(String(target))).map(r=>String(r.id));if(scope==='stage'){if(target==='Quarantine'){const q=new Set(quarantineCases().map(c=>String(c.imageId||'')));return all.filter(r=>q.has(String(r.id))).map(r=>String(r.id))}if(target==='Recycle')return all.filter(r=>r.attributes?.inRecycleBin).map(r=>String(r.id));if(target==='Purgatory')return all.filter(r=>r.workflow?.stage==='purgatory').map(r=>String(r.id));if(target==='Inbox')return all.filter(r=>r.workflow?.stage==='inbox-working').map(r=>String(r.id));return all.filter(r=>stageOf(r)===target||String(r.workflow?.stage||'')===target).map(r=>String(r.id))}return [...state.selected]}
