async function purgeDiagnostics(){const names=await existingDatabaseNames(),count=await clearStore('genreactrix-prompt-diagnostics','runs',names);return{diagnosticRuns:count}}
async function resetAllProductData(){const names=await existingDatabaseNames(),groups=await targetStoreGroups(names),totalStores=groups.reduce((n,g)=>n+g.stores.length,0),cleared=[];let done=0;await yieldToBrowser();for(const {dbName,stores} of groups){setStatus('dangerZoneExecuteStatus',`Clearing ${done+1}–${done+stores.length} of ${totalStores} stores · ${dbName}…`);await clearDatabaseStores(dbName,stores,names);for(const store of stores)cleared.push({dbName,store});done+=stores.length;setStatus('dangerZoneExecuteStatus',`Cleared ${done} of ${totalStores} stores…`);await yieldToBrowser()}clearFullLocalProduct();setStatus('dangerZoneExecuteStatus',`Cleared ${totalStores} of ${totalStores} stores · verifying…`);await yieldToBrowser();return{cleared,stores:cleared.length}}
async function verifyPostDelete(mode,ids=[]){const names=await existingDatabaseNames(),checks=[],idset=new Set(ids.map(String));if(mode==='reset-all'){const left=recordsFromLocal().length;checks.push({name:'Image Records',ok:left===0,detail:`${left} remain`});const plans=Object.entries(FULL_DB_PLAN).filter(([dbName])=>names.has(dbName));let verified=0;for(let dbIndex=0;dbIndex<plans.length;dbIndex++){const [dbName,plan]=plans[dbIndex];setStatus('dangerZoneExecuteStatus',`Final verification · database ${dbIndex+1}/${plans.length} · ${dbName}…`);const db=await openExistingDb(dbName,names);if(!db)continue;try{const stores=plan==='*'?[...db.objectStoreNames]:plan.filter(store=>db.objectStoreNames.contains(store));for(const store of stores){const hasRecord=await storeHasAnyRecordInDb(db,dbName,store);checks.push({name:`${dbName}/${store}`,ok:!hasRecord,detail:hasRecord?'at least 1 record remains':'empty'});verified++;await yieldToBrowser(FAILSAFE_YIELD_MS)}}finally{db.close()}}for(const key of PRODUCT_LOCAL_KEYS)for(const k of projectScopedKeys(key))if(localStorage.getItem(k)!=null)checks.push({name:`localStorage ${k}`,ok:false,detail:'still present'});setStatus('dangerZoneExecuteStatus',`Count-free verification checked ${verified} store(s).`)}else if(mode==='diagnostics'){const counts=await countDatabaseStores('genreactrix-prompt-diagnostics',['runs'],names),count=Number(counts.runs)||0;checks.push({name:'Prompt Diagnostics runs',ok:count===0,detail:`${count} remain`})}else{const left=recordsFromLocal().filter(r=>idset.has(String(r.id))).length;checks.push({name:'Selected Image Records',ok:mode==='derived'||left===0,detail:mode==='derived'?'preserved by design':`${left} remain`})}return{ok:checks.every(x=>x.ok),checks,issueCount:checks.filter(x=>!x.ok).length}}
