async function runConfirmedCleanup({resume=false}={}){if(state.executing||!state.impact)return;state.executing=true;$('dangerZoneExecute').disabled=true;document.querySelectorAll('input[name="dangerZoneResetMethod"]').forEach(r=>r.disabled=true);try{let result;if(state.impact.mode==='reset-all'&&state.resetMethod==='failsafe'){setStatus('dangerZoneExecuteStatus',resume?'Resuming failsafe cleanup from the saved checkpoint…':'Preparing failsafe cleanup…');await yieldToBrowser(FAILSAFE_YIELD_MS);result=await failsafeResetAllProductData();if(result?.paused||result?.stopped)return}else if(state.impact.mode==='reset-all'){setStatus('dangerZoneExecuteStatus','Preparing memory-safe fast cleanup…');await yieldToBrowser();result=await resetAllProductData()}else if(state.impact.mode==='diagnostics')result=await purgeDiagnostics();else if(state.impact.mode==='derived')result=await selectiveCascade(state.impact.imageIds,{derivedOnly:true});else result=await selectiveCascade(state.impact.imageIds,{derivedOnly:false});await finishCleanupRun(result)}catch(error){const retry=state.impact?.mode==='reset-all'?' You can safely retry Reset All Product Data.':'';setStatus('dangerZoneExecuteStatus',`${error?.message||String(error)}${retry}`,true);if(state.resetMethod==='failsafe')renderFailsafeControls({stopped:true})}finally{state.executing=false;document.querySelectorAll('input[name="dangerZoneResetMethod"]').forEach(r=>r.disabled=false);checkFinalReady()}}
